#include <bits/stdc++.h>
using namespace std;

struct State {
    int x, y, idx;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int sx, sy, gx, gy;
    cin >> sx >> sy >> gx >> gy;

    int minX, maxX, minY, maxY;
    cin >> minX >> maxX >> minY >> maxY;

    int n;
    cin >> n;
    vector<string> dirs(n);
    for (int i = 0; i < n; i++) {
        cin >> dirs[i];
    }

    int k;
    cin >> k;
    set<pair<int,int>> obstacles;
    for (int i = 0; i < k; i++) {
        int ox, oy;
        cin >> ox >> oy;
        obstacles.insert({ox, oy});
    }

    // Direction offsets for hex axial coordinates
    map<string, pair<int,int>> offset = {
        {"n",  {0, -1}},
        {"s",  {0, 1}},
        {"ne", {1, -1}},
        {"nw", {-1, 0}},
        {"se", {1, 0}},
        {"sw", {-1, 1}}
    };

    // 0-1 BFS
    // dist[x][y][idx] -> large number for infinite
    const int INF = 1e9;
    // We'll use map for sparse storage, since coordinates range is not huge but idx up to 50
    // But coordinate range unknown, so map of map is safer.
    // We'll store dist as map from (x,y) to vector of distances for each idx.
    map<pair<int,int>, vector<int>> dist;
    deque<State> dq;

    auto getDist = [&](int x, int y, int idx) -> int& {
        auto &vec = dist[{x, y}];
        if (vec.empty()) vec.assign(n+1, INF);
        return vec[idx];
    };

    getDist(sx, sy, 0) = 0;
    dq.push_back({sx, sy, 0});

    auto inside = [&](int x, int y) -> bool {
        return x >= minX && x <= maxX && y >= minY && y <= maxY;
    };

    auto blocked = [&](int x, int y) -> bool {
        return obstacles.count({x, y});
    };

    while (!dq.empty()) {
        State cur = dq.front(); dq.pop_front();
        int d = getDist(cur.x, cur.y, cur.idx);

        if (cur.x == gx && cur.y == gy) {
            cout << d << "\n";
            return 0;
        }

        if (cur.idx < n) {
            // Option 1: follow direction
            string dir = dirs[cur.idx];
            auto [dx, dy] = offset[dir];
            int nx = cur.x + dx;
            int ny = cur.y + dy;
            if (inside(nx, ny) && !blocked(nx, ny)) {
                int &nd = getDist(nx, ny, cur.idx+1);
                if (d < nd) {
                    nd = d;
                    dq.push_front({nx, ny, cur.idx+1});
                }
            }

            // Option 2: ignore direction
            int &nd2 = getDist(cur.x, cur.y, cur.idx+1);
            if (d+1 < nd2) {
                nd2 = d+1;
                dq.push_back({cur.x, cur.y, cur.idx+1});
            }
        } else {
            // No more sister directions, move freely
            for (auto &[name, off] : offset) {
                auto [dx, dy] = off;
                int nx = cur.x + dx;
                int ny = cur.y + dy;
                if (inside(nx, ny) && !blocked(nx, ny)) {
                    int &nd = getDist(nx, ny, n);
                    if (d+1 < nd) {
                        nd = d+1;
                        dq.push_back({nx, ny, n});
                    }
                }
            }
        }
    }

    cout << -1 << "\n";
    return 0;
}

