int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    int sx, sy, gx, gy;
    cin >> sx >> sy >> gx >> gy;

    vector<string> dir(K);
    for (int i = 0; i < K; ++i) cin >> dir[i];

    vector<vector<bool>> blocked(N + 1, vector<bool>(M + 1, false));
    int B;
    cin >> B;
    for (int i = 0; i < B; ++i) {
        int x, y;
        cin >> x >> y;
        if (1 <= x && x <= N && 1 <= y && y <= M) blocked[x][y] = true;
    }

    if (sx < 1 || sx > N || sy < 1 || sy > M ||
        gx < 1 || gx > N || gy < 1 || gy > M ||
        blocked[sx][sy] || blocked[gx][gy]) {
        cout << -1 << '\n';
        return 0;
    }

    map<string, pair<int,int>> mp;
    mp["N"]  = {-1, 0};
    mp["S"]  = { 1, 0};
    mp["NW"] = { 0,-1};
    mp["NE"] = { 0, 1};
    mp["SW"] = { 1,-1};
    mp["SE"] = { 1, 1};

    vector<pair<int,int>> moves = {
        {-1,0}, {1,0}, {0,-1}, {0,1}, {1,-1}, {1,1}
    };

    const int INF = 1e9;
    vector<vector<vector<int>>> dist(
        K + 1, vector<vector<int>>(N + 1, vector<int>(M + 1, INF))
    );

    deque<State> dq;
    dist[0][sx][sy] = 0;
    dq.push_back({sx, sy, 0});

    while (!dq.empty()) {
        auto [x, y, t] = dq.front();
        dq.pop_front();

        int cur = dist[t][x][y];
        if (t == K) continue;

        auto [dx0, dy0] = mp[dir[t]];

        for (auto [dx, dy] : moves) {
            int nx = x + dx, ny = y + dy;
            if (nx < 1 || nx > N || ny < 1 || ny > M) continue;
            if (blocked[nx][ny]) continue;

            int w = (dx == dx0 && dy == dy0) ? 0 : 1;
            if (dist[t + 1][nx][ny] > cur + w) {
                dist[t + 1][nx][ny] = cur + w;
                if (w == 0) dq.push_front({nx, ny, t + 1});
                else dq.push_back({nx, ny, t + 1});
            }
        }
    }

    int ans = INF;
    for (int t = 0; t <= K; ++t) {
        ans = min(ans, dist[t][gx][gy]);
    }

    cout << (ans == INF ? -1 : ans) << '\n';
    return 0;
}

