#define INF 1000000000

typedef struct {
    int x, y;
} Point;

typedef struct {
    int to, w, next;
} Edge;

typedef struct {
    int v, d;
} HeapNode;

static int cmpPoint(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

static int lower_bound_point(Point *arr, int n, Point key) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        int c;
        if (arr[m].x != key.x) c = (arr[m].x < key.x) ? -1 : 1;
        else if (arr[m].y != key.y) c = (arr[m].y < key.y) ? -1 : 1;
        else c = 0;
        if (c < 0) l = m + 1;
        else r = m;
    }
    return l;
}

static int find_point(Point *arr, int n, int x, int y) {
    Point key = {x, y};
    int idx = lower_bound_point(arr, n, key);
    if (idx < n && arr[idx].x == x && arr[idx].y == y) return idx;
    return -1;
}

/* Min-heap for Dijkstra */
static void heap_push(HeapNode *heap, int *sz, HeapNode val) {
    int i = ++(*sz);
    while (i > 1) {
        int p = i >> 1;
        if (heap[p].d <= val.d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i] = val;
}

static HeapNode heap_pop(HeapNode *heap, int *sz) {
    HeapNode ret = heap[1];
    HeapNode last = heap[(*sz)--];
    int i = 1;
    while ((i << 1) <= *sz) {
        int l = i << 1, r = l + 1, c = l;
        if (r <= *sz && heap[r].d < heap[l].d) c = r;
        if (heap[c].d >= last.d) break;
        heap[i] = heap[c];
        i = c;
    }
    heap[i] = last;
    return ret;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int sx, sy, gx, gy;
    scanf("%d %d %d %d", &sx, &sy, &gx, &gy);

    char s[200005];
    scanf("%s", s);
    int L = (int)strlen(s);

    Point *obs = (Point *)malloc(sizeof(Point) * n);
    for (int i = 0; i < n; i++) scanf("%d %d", &obs[i].x, &obs[i].y);

    /* Candidate nodes:
       start, goal, obstacles, and all neighbors of these points.
       On a hex grid, straight movement cost between two visible nodes is
       number of steps, and instruction-mismatch cost along a segment can be computed.
    */

    int dx[6] = {1, 0, -1, -1, 0, 1};
    int dy[6] = {0, 1, 1, 0, -1, -1};

    int cap = 2 + n + 6 * (2 + n);
    Point *pts = (Point *)malloc(sizeof(Point) * cap);
    int m = 0;

    pts[m++] = (Point){sx, sy};
    pts[m++] = (Point){gx, gy};
    for (int i = 0; i < n; i++) pts[m++] = obs[i];
    pts[m++] = (Point){sx, sy}; /* harmless duplicates possible */

    for (int i = 0; i < n; i++) {
        for (int d = 0; d < 6; d++) {
            pts[m++] = (Point){obs[i].x + dx[d], obs[i].y + dy[d]};
        }
    }
    for (int d = 0; d < 6; d++) {
        pts[m++] = (Point){sx + dx[d], sy + dy[d]};
        pts[m++] = (Point){gx + dx[d], gy + dy[d]};
    }

    qsort(pts, m, sizeof(Point), cmpPoint);

    int uniq = 0;
    for (int i = 0; i < m; i++) {
        if (uniq == 0 || pts[i].x != pts[uniq - 1].x || pts[i].y != pts[uniq - 1].y) {
            pts[uniq++] = pts[i];
        }
    }
    m = uniq;

    qsort(obs, n, sizeof(Point), cmpPoint);

    int start = find_point(pts, m, sx, sy);
    int goal = find_point(pts, m, gx, gy);

    /* Prefix counts of instructions per direction */
    int (*pref)[6] = malloc(sizeof(int[6]) * (L + 1));
    for (int d = 0; d < 6; d++) pref[0][d] = 0;

    int mapdir[256];
    for (int i = 0; i < 256; i++) mapdir[i] = -1;
    /* Assume directions encoded as E, NE, NW, W, SW, SE by chars 0..5 style:
       Since original statement text is omitted, support common 6-char set:
       'A','B','C','D','E','F' impossible to infer.
       We map digits 0..5 and letters a..f/A..F and also
       e,n,w,s combinations are not single-char.
       Therefore assume input uses digits 0..5 or letters 1..6-like.
    */
    mapdir['0'] = 0; mapdir['1'] = 1; mapdir['2'] = 2;
    mapdir['3'] = 3; mapdir['4'] = 4; mapdir['5'] = 5;
    mapdir['A'] = 0; mapdir['B'] = 1; mapdir['C'] = 2;
    mapdir['D'] = 3; mapdir['E'] = 4; mapdir['F'] = 5;
    mapdir['a'] = 0; mapdir['b'] = 1; mapdir['c'] = 2;
    mapdir['d'] = 3; mapdir['e'] = 4; mapdir['f'] = 5;

    for (int i = 0; i < L; i++) {
        for (int d = 0; d < 6; d++) pref[i + 1][d] = pref[i][d];
        int dir = mapdir[(unsigned char)s[i]];
        if (dir >= 0) pref[i + 1][dir]++;
    }

    /* Build visibility graph */
    int maxEdges = m * 12 + 10;
    Edge *edges = (Edge *)malloc(sizeof(Edge) * maxEdges);
    int *head = (int *)malloc(sizeof(int) * m);
    for (int i = 0; i < m; i++) head[i] = -1;
    int ecnt = 0;

    for (int i = 0; i < m; i++) {
        for (int d = 0; d < 6; d++) {
            int x = pts[i].x, y = pts[i].y;
            int step = 0;
            while (1) {
                x += dx[d];
                y += dy[d];
                step++;

                if (find_point(obs, n, x, y) != -1) break; /* blocked by obstacle */

                int j = find_point(pts, m, x, y);
                if (j != -1) {
                    /* Cost to move 'step' times in direction d:
                       among first min(step,L) instructions, matches on d are free,
                       all others ignored; extra steps beyond L are all ignored.
                    */
                    int use = step < L ? step : L;
                    int matches = pref[use][d];
                    int cost = step - matches;

                    if (ecnt + 2 > maxEdges) {
                        maxEdges *= 2;
                        edges = (Edge *)realloc(edges, sizeof(Edge) * maxEdges);
                    }
                    edges[ecnt] = (Edge){j, cost, head[i]};
                    head[i] = ecnt++;
                }
            }
        }
    }

    int *dist = (int *)malloc(sizeof(int) * m);
    for (int i = 0; i < m; i++) dist[i] = INF;
    dist[start] = 0;

    HeapNode *heap = (HeapNode *)malloc(sizeof(HeapNode) * (ecnt + m + 5));
    int hsz = 0;
    heap_push(heap, &hsz, (HeapNode){start, 0});

    while (hsz) {
        HeapNode cur = heap_pop(heap, &hsz);
        int v = cur.v;
        if (cur.d != dist[v]) continue;
        if (v == goal) break;

        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            int nd = dist[v] + edges[e].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(heap, &hsz, (HeapNode){to, nd});
            }
        }
    }

    if (dist[goal] >= INF) printf("-1\n");
    else printf("%d\n", dist[goal]);

    free(obs);
    free(pts);
    free(pref);
    free(edges);
    free(head);
    free(dist);
    free(heap);
    return 0;
}

